                                    "heading":  "सागर सर द्वारा सुझाए गए विशेष तैयारी सूत्र एवं शॉर्टकट ट्रिक्स",
                                    "subheading":  "कम समय में सटीक उत्तर तक पहुँचने की प्रमाणित रणनीतियाँ",
                                    "paragraphs":  [
                                                       "इस प्रश्न पत्र को हल करते समय छात्रों को सबसे पहले आसान और तथ्य-आधारित प्रश्नों को हल करना चाहिए। विशेषकर गणित और रीजनिंग में लंबे गुणा-भाग में उलझने के बजाय विकल्पों को ध्यान से देखें और एलिमिनेशन मेथड (Elimination Method) का प्रयोग करें।",
                                                       "परीक्षा के अंतिम 15 मिनट केवल OMR शीट की री-चेकिंग और छूटे हुए प्रश्नों के अनुमानित उत्तर लगाने के लिए सुरक्षित रखें। याद रखें, एक-एक अंक मेरिट लिस्ट में आपकी रैंक और छात्रवृत्ति चयन को सुनिश्चित करता है।"
                                                   ],
