                                                         "नेगेटिव मार्किंग नहीं होने के कारण किसी भी प्रश्न को बिना हल किए न छोड़ें।",
                                                         "गलत हुए प्रश्नों के कॉन्सेप्ट को तुरंत अपनी रिवीजन नोटबुक में नोट करें।"
