                                                         "प्रत्येक प्रश्न के लिए 1 अंक निर्धारित है और गलत उत्तर पर कोई ऋणात्मक अंकन (Negative Marking) नहीं है।",
                                                         "ओएमआर (OMR) शीट भरने का पूर्वाभ्यास करने के लिए सबसे प्रामाणिक अध्ययन सामग्री।"
